-- Target query filters orders on (status, order_date). This composite index
-- lets the planner use a bitmap index scan on orders instead of a seq scan.
-- Column order: equality column (status) first, range column (order_date) second.
CREATE INDEX orders_status_date_idx ON orders (status, order_date);

-- Foreign-key index for the order_items -> orders join (and for FK checks/deletes).
CREATE INDEX order_items_order_id_idx ON order_items (order_id);

